import{z as A,x as B,o as r,c as d,q as n,j as t,D as e,d as E,s as i,S as o,b as s}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"嵌套循环与哈希连接","description":"","frontmatter":{"title":"嵌套循环与哈希连接","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/nlj-hash-join.md","filePath":"cs/nlj-hash-join.md","lastUpdated":1791413859000}'),p={name:"cs/nlj-hash-join.md"};function h(m,a,c,u,f,D){const l=B("Mermaid");return r(),d("div",null,[a[2]||(a[2]=n('<h1 id="嵌套循环与哈希连接" tabindex="-1">嵌套循环与哈希连接 <a class="header-anchor" href="#嵌套循环与哈希连接" aria-label="Permalink to &quot;嵌套循环与哈希连接&quot;">​</a></h1><div class="epigraph"><p>嵌套循环对每一外层元组探测内层；哈希连接把较小一侧建成桶，另一侧探测——代价形状完全不同。</p><footer>—— 据 Blasgen and Eswaran；Ramakrishnan and Gehrke 对 NLJ 与哈希连接的整理</footer></div><p><a href="/cs/join-algorithms">上一课</a>声明逻辑连接只有一种含义、物理有三种形状。本课不重写 ⋈ 的定义。缺口是前两种算子：块嵌套循环如何用缓冲池，哈希连接如何在内存不够时分区。排序归并下一课。NULL 不当成匹配键，<a href="/cs/sql-null">空值与三值逻辑</a> 已钉。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>连接算法总览留下名字。嵌套循环：简单，有索引时可变成「外层扫描 + 内层索引探测」。无索引则内层反复全表，I/O 灾难。哈希：等值连接上把 build 输入散到桶，probe 输入只扫一次；内存不够则 Grace 式分区再递归。缺口是<strong>何时选哪一种</strong>的机制，数字在代价课。</p><p><span class="marginnote">非等值连接（θ 不是等）哈希帮不上忙，循环或排序更合适。构建侧应是较小的那张（估计后）。</span></p><p><span class="marginnote">数字实例：外层 1000 页、内层 100 页的块 NLJ，每批读 10 页外层，代价约 \\((1000/10)\\times100=10000\\) 次 I/O；若内层连接键有索引，每次探测只要几次 I/O——选算法前先看表大小与索引。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>块 NLJ：一次读外层 B 页，内层扫一遍，摊薄内层 I/O。索引 NLJ：内层条件是键，走 B+。哈希：选哈希函数，处理溢出桶；混合哈希把一部分常驻内存。本课不写具体 DBMS 的算子名。</p><p><span class="marginnote">直觉类比：哈希连接像聚会前先把客人按姓氏首字母分进房间，后来的客人报出姓直接去对应房间找人——先「分房」（build）再「对号」（probe），不用每个新客人和全场逐一握手（嵌套循环）。</span></p>',10)),(r(),t(o,null,{default:e(()=>[i(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20EQ%5B%22%E7%AD%89%E5%80%BC%E8%BF%9E%E6%8E%A5%22%5D%20--%3E%20NLJ%5B%22%E5%B5%8C%E5%A5%97%E5%BE%AA%E7%8E%AF%20%2F%20%E7%B4%A2%E5%BC%95%E6%8E%A2%E6%B5%8B%22%5D%0A%20%20EQ%20--%3E%20HJ%5B%22%E5%BB%BA%E5%93%88%E5%B8%8C%E8%A1%A8%E5%86%8D%E6%8E%A2%E6%B5%8B%22%5D%0A%20%20MEM%5B%22%E5%86%85%E5%AD%98%E4%B8%8D%E5%A4%9F%22%5D%20--%3E%20PART%5B%22%E5%88%86%E5%8C%BA%E5%90%8E%E5%86%8D%E5%93%88%E5%B8%8C%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[E("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,[E("两种算子实现同一代数，但打破对称：哪一侧在外/build 改变页数。缓冲池偷页与脏页规则仍是 "),s("a",{href:"/cs/wal"},"WAL"),E(" 之前的那一套文件 I/O。选择率估错会选错 build 侧，后课直方图补统计。")],-1)),(r(),t(o,null,{default:e(()=>[i(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20B%5B%22build%20%E4%BE%A7%EF%BC%9A%E8%BE%83%E5%B0%8F%E7%9A%84%E8%A1%A8%22%5D%20--%3E%20H%5B%22%E6%8C%89%E8%BF%9E%E6%8E%A5%E9%94%AE%E6%95%A3%E5%88%97%E8%BF%9B%E5%86%85%E5%AD%98%E6%A1%B6%22%5D%0A%20%20H%20--%3E%20HT%5B%22%E5%93%88%E5%B8%8C%E8%A1%A8%E5%B0%B1%E7%BB%AA%22%5D%0A%20%20P%5B%22probe%20%E4%BE%A7%EF%BC%9A%E8%BE%83%E5%A4%A7%E7%9A%84%E8%A1%A8%22%5D%20--%3E%7C%22%E9%80%90%E8%A1%8C%E5%8F%AA%E6%89%AB%E4%B8%80%E9%81%8D%22%7C%20LK%5B%22%E6%8C%89%E9%94%AE%E5%93%88%E5%B8%8C%E5%AE%9A%E4%BD%8D%E6%A1%B6%22%5D%0A%20%20HT%20--%3E%20LK%0A%20%20LK%20--%3E%20M%5B%22%E6%A1%B6%E5%86%85%E6%AF%94%E5%AF%B9%20%E2%87%92%20%E8%BE%93%E5%87%BA%E8%BF%9E%E6%8E%A5%E7%BB%93%E6%9E%9C%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p>这张图回答：哈希连接内部的两阶段怎么协作。build 阶段一次性把小表按键分桶，probe 阶段大表每行只探一次桶——代价从「两边相乘」变成「两边相加」，这正是它与嵌套循环的本质差别。</p><p><span class="marginnote">常见误区：初学者容易以为哈希连接永远更快。它要整表过一遍哈希、对内存敏感，非等值条件（如 \\(\\lt\\)）根本用不上桶；小表外层加索引探测的嵌套循环常常反而赢——优化器靠统计估计来选，估计错就选错。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把并行 hash join 的全部网络 shuffle 写入主干。两边已按连接键有序时，归并可以一次扫描，下一课。</p><p>后课默认：等值连接常用循环或哈希。有序输入另有归并。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NLJ 简单，索引时变成探测。</li><li>哈希适合等值且能放下或能分区。</li><li>排序归并下一课。</li><li>出处：Blasgen and Eswaran；Ramakrishnan and Gehrke。</li></ul>',7))])}const C=A(p,[["render",h]]);export{b as __pageData,C as default};
